   <script>
     const quizForm = document.getElementById('quiz-form');
     const statusMessage = document.getElementById('quiz-status');
     const resultsPanel = document.getElementById('quiz-results');
     const resultsList = document.getElementById('results-list');
     const questions = Array.from(quizForm.querySelectorAll('fieldset'));

     function setGroupState(fieldset, isValid) {
       const fieldWrapper = fieldset.closest('.form-field');
       const errorMessage = document.getElementById(fieldset.id + '-error');

       fieldWrapper.classList.toggle('invalid', !isValid);
       errorMessage.hidden = isValid;

       if (isValid) {
         fieldset.setAttribute('aria-describedby', fieldset.dataset.baseDescribedBy);
         return;
       }

       fieldset.setAttribute('aria-describedby', fieldset.dataset.baseDescribedBy);
     }

     function getCheckedOptions(fieldset) {
       return Array.from(fieldset.querySelectorAll('input[type="checkbox"]:checked'));
     }

     function validateGroups() {
       let firstInvalidCheckbox = null;

       for (const fieldset of questions) {
         const checkedOptions = getCheckedOptions(fieldset);
         const isValid = checkedOptions.length > 0;
         setGroupState(fieldset, isValid);

         if (!isValid && !firstInvalidCheckbox) {
           firstInvalidCheckbox = fieldset.querySelector('input[type="checkbox"]');
         }
       }

       return firstInvalidCheckbox;
     }

     function isQuestionCorrect(fieldset) {
       const inputs = Array.from(fieldset.querySelectorAll('input[type="checkbox"]'));
       return inputs.every((input) => input.checked === (input.dataset.correct === 'true'));
     }

     function renderSelections() {
       const items = questions.map((fieldset) => {
         const legend = fieldset.querySelector('legend').textContent;
         const selections = getCheckedOptions(fieldset).map((input) => input.value);
         const item = document.createElement('li');
         item.textContent = legend + ' ' + selections.join(', ');
         return item;
       });

       resultsList.replaceChildren(...items);
       resultsPanel.hidden = false;
     }

     quizForm.addEventListener('submit', (event) => {
       event.preventDefault();
       statusMessage.textContent = '';
       resultsPanel.hidden = true;

       const firstInvalidCheckbox = validateGroups();

       if (firstInvalidCheckbox) {
         firstInvalidCheckbox.focus();
         return;
       }

       const score = questions.filter(isQuestionCorrect).length;
       statusMessage.textContent = 'You scored ' + score + ' out of ' + questions.length + '.';
       renderSelections();
     });

     quizForm.addEventListener('change', (event) => {
       const target = event.target;

       if (!(target instanceof HTMLInputElement) || target.type !== 'checkbox') {
         return;
       }

       const fieldset = target.closest('fieldset');

       if (fieldset) {
         setGroupState(fieldset, getCheckedOptions(fieldset).length > 0);
       }
     });
   </script>
